const transaction=id=>{
 const rollback=id==='db-027',durable=id==='db-030',both=['db-010','db-022','db-025'].includes(id);
 const result=both?tag('모두 성공 → COMMIT','골드 0 · 아이템 1',true)+tag('실패 → ROLLBACK','골드 100 · 아이템 0'):tag('골드',rollback?'100':'0',true)+tag('아이템 수',rollback?'0':'1',true);
 return picture(`<div class="gv-scenes">${scene('1. 구매 전 · BEGIN',tag('골드','100')+tag('아이템 수','0'),'거래를 시작하고 차감·지급을 함께 다뤄요.')}${scene(durable?'2. COMMIT 완료':'2. 거래 진행 중',tag('골드','0')+tag('아이템 수',durable?'1':'0')+(durable?'<b class="gv-confirmed">확정</b>':'<b class="gv-unconfirmed">아직 확정하지 않음</b>'),'차감만 남긴 채 구매 성공으로 처리하지 않아요.')}${scene(durable?'3. 재시작 뒤':both?'3. 두 결과 중 하나':rollback?'3. ROLLBACK':'3. COMMIT',result,durable?'약속한 장애 범위에서 확정 결과를 보존해요.':rollback?'실패하면 확정 전 변경을 취소해요.':both?'반쪽 변경을 확정하지 않아요.':'지급까지 성공한 변경을 함께 확정해요.')}</div>`,durable?'골드100 아이템0에서 구매해 골드0 아이템1로 커밋한 뒤 재시작해도 확정 결과를 보존하는 지속성':rollback?'골드100 아이템0에서 골드만 차감한 미확정 상태가 롤백 뒤 골드100 아이템0으로 돌아오는 결과':both?'골드100 아이템0에서 시작해 성공은 골드0 아이템1로 커밋하고 실패는 골드100 아이템0으로 롤백하는 두 결과':'골드100 아이템0에서 골드를 차감하고 아이템을 지급한 뒤 골드0 아이템1로 확정하는 커밋');
};
