const arrayList=()=>picture(`<div class="gv-route-title">배열 · 인벤토리 [검, 방패, 포션]</div><div class="gv-indexed-array">${['검','방패','포션'].map((x,i)=>`<div><small>인덱스 ${i}</small><b>${x}</b></div>`).join('')}</div><div class="gv-equation">길이 3 · 마지막 인덱스 2 · 인덱스 1 → 방패</div><div class="gv-route-title">연결 리스트 · 다음 참조로 이동</div>${flow(['검','방패','포션'].map(x=>`<div class="gv-list-node">${x}<small>다음 참조</small></div>`))}`,'배열 인벤토리 검 방패 포션에 인덱스 0 1 2를 표시하고 길이 3과 마지막 인덱스 2를 비교함. 연결 리스트는 다음 참조의 화살표로 이동함');
const spaceComplexity=()=>picture(`<div class="gv-scenes two">${scene('합계 하나만 보관',tag('n = 5','추가 합계 칸 1개')+tag('n = 10','추가 합계 칸 1개')+cells(['합계']),'입력 밖에 필요한 추가 공간이 일정해요: O(1).')}${scene('입력 전체를 복사',tag('n = 5','복사 칸 5개')+cells(['1','2','3','4','5'])+tag('n = 10','복사 칸 10개')+cells(Array.from({length:10},(_,i)=>String(i+1))),'입력 밖의 추가 공간도 n에 비례해요: O(n).')}</div>`,'입력 저장 공간은 별도로 두고, 합계 계산은 추가 한 칸, 전체 복사는 입력 수만큼 추가 칸을 사용하는 두 알고리즘의 공간 비교');
const hashTable=()=>picture(`<div class="gv-scenes two">${scene('1. 키로 버킷 계산',table(['키','학습용 h(키)','h % 4'],[['I1','1','1'],['I5','5','1']],{col:2}),'설명용 해시 함수는 I 뒤의 숫자를 값으로 써요.')}${scene('2. 같은 버킷에 연결',`<div class="gv-hash-bucket"><b>버킷 1</b>${flow([tag('키 I1','값: 검'),tag('키 I5','값: 활')])}</div>`,'I5를 찾을 때 I1과 I5의 원래 키를 비교해요.')}</div><div class="gv-rule">다른 키 → 같은 버킷: 둘 다 보관하고 구별해요.</div>`,'설명용 해시에서 I1은 1, I5는 5이며 4로 나눈 나머지는 모두 1. 버킷 1에 I1 검과 I5 활을 체이닝하고 조회 시 원래 키를 비교함');
function nodeGraph(nodes,edges,{directed=false,highlight=[],subtree=false}={}){
 const byKey=new Map(nodes.map(n=>[n[0],n]));
 return `<svg class="gv-node-graph" viewBox="0 0 360 240" role="img" aria-label="${e(nodes.map(n=>n[0]).join(' · '))}의 연결 관계">${subtree?'<rect class="gv-subtree-boundary" x="20" y="76" width="170" height="152" rx="14"/>':''}${edges.map(([from,to])=>{const a=byKey.get(from),b=byKey.get(to),dx=b[1]-a[1],dy=b[2]-a[2],len=Math.hypot(dx,dy),ux=dx/len,uy=dy/len,x=b[1]-ux*23,y=b[2]-uy*23;return `<g data-from="${e(from)}" data-to="${e(to)}"><line x1="${a[1]+ux*22}" y1="${a[2]+uy*22}" x2="${x}" y2="${y}"/>${directed?`<polygon points="${x},${y} ${x-ux*10-uy*5},${y-uy*10+ux*5} ${x-ux*10+uy*5},${y-uy*10-ux*5}"/>`:''}</g>`;}).join('')}${nodes.map(([name,x,y])=>`<g class="${highlight.includes(name)?'is-focus':''}"><circle cx="${x}" cy="${y}" r="21"/><text x="${x}" y="${y+7}">${e(name)}</text></g>`).join('')}</svg>`;
}
