const treeParts=id=>picture(`${nodeGraph(basicTreeNodes,basicTreeEdges,{subtree:id==='ds-053',highlight:id==='ds-052'?['A','B','D']:id==='ds-053'?['B','D','E']:id==='ds-087'?['C']:[]})}${table(['노드','깊이 · 루트부터','높이 · 가장 먼 리프까지'],[['A','0','2'],['B','1','1'],['D','2','0']],{col:id==='ds-052'?2:id==='ds-051'?1:-1})}${id==='ds-053'?'<div class="gv-rule">점선 안 B·D·E 전체가 B를 루트로 한 서브트리예요.</div>':''}`,'루트 A, 자식 B와 C, B의 자식 D와 E인 트리. A의 깊이는 0 높이는 2, B의 깊이는 1 높이는 1, D의 깊이는 2 높이는 0');
